#!/usr/bin/env -S uv run --script
# /// script
# requires-python = ">=3.9"
# dependencies = []
# ///
#lock-deps.py D.S. Leonard 2026
# like uv lock --upgrade --refressh, but for cmake :P 
# uses CPM lock file but makes it better.
# Now you can use branch names for tags, but can lock to shas and update automatically.

"""Merge / refresh CPM package locks.

  lock-deps.py merge   --build BUILD_DIR [--lock package-lock.cmake] [--prune]
  lock-deps.py refresh --build BUILD_DIR [--lock package-lock.cmake] (--all | NAME ...)

merge:   keep every existing pin, resolve only names not yet in the lock.
refresh: re-resolve the listed names (or all) to current SHAs. BUILD_DIR must come
         from an UNPINNED configure so its entries carry loose refs (master, v1.2).
"""
import argparse, os, re, subprocess, sys

BLOCK = re.compile(r"^CPMDeclarePackage\(\s*([^\s)]+)(.*?)^\)", re.S | re.M)
SHA40 = re.compile(r"^[0-9a-f]{40}$")


def parse(path):
    """-> ordered {name: full block text}. Commented-out entries are ignored."""
    if not os.path.exists(path):
        return {}
    text = open(path, encoding="utf-8").read()
    return {m.group(1): m.group(0) for m in BLOCK.finditer(text)}


def field(block, key):
    m = re.search(rf"(?:^|\s){key}\s+(\S+)", block)
    return m.group(1) if m else None


def resolve(repo, ref):
    if SHA40.match(ref):
        return ref
    env = dict(os.environ, GIT_TERMINAL_PROMPT="0")
    r = subprocess.run(
        ["git", "ls-remote", repo, f"refs/heads/{ref}", f"refs/tags/{ref}", f"refs/tags/{ref}^{{}}"],
        capture_output=True, text=True, env=env)
    if r.returncode != 0:
        sys.exit(f"git ls-remote failed for {repo}: {r.stderr.strip()}")
    found = {}
    for line in r.stdout.splitlines():
        sha, name = line.split("\t")
        found[name] = sha
    for key in (f"refs/tags/{ref}^{{}}", f"refs/heads/{ref}", f"refs/tags/{ref}"):  # peeled tag first
        if key in found:
            return found[key]
    sys.exit(f"cannot resolve '{ref}' in {repo}")


def pin(name, block):
    repo, ref = field(block, "GIT_REPOSITORY"), field(block, "GIT_TAG")
    if not repo or not ref:
        print(f"  {name}: no GIT_REPOSITORY/GIT_TAG, copied as is")
        return block
    sha = resolve(repo, ref)
    print(f"  {name}: {ref} -> {sha[:12]}")
    return re.sub(rf"(\bGIT_TAG\s+){re.escape(ref)}", rf"\g<1>{sha} # {ref}", block, count=1)


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("cmd", choices=["merge", "refresh"])
    ap.add_argument("names", nargs="*")
    ap.add_argument("--build", required=True, help="build dir containing cpm-package-lock.cmake")
    ap.add_argument("--lock", default="package-lock.cmake")
    ap.add_argument("--all", action="store_true", help="refresh: every package")
    ap.add_argument("--prune", action="store_true", help="drop lock entries not seen in this configure")
    a = ap.parse_args()

    new = parse(os.path.join(a.build, "cpm-package-lock.cmake"))
    old = parse(a.lock)
    if not new:
        sys.exit("no entries in the build dir's cpm-package-lock.cmake "
                 "(did you set CPM_INCLUDE_ALL_IN_PACKAGE_LOCK and configure?)")

    targets = set(a.names)
    if a.cmd == "refresh":
        if not (a.all or targets):
            sys.exit("refresh needs --all or package names")
        for n in targets - set(new):
            print(f"  warning: {n} not in this configure (overridden or misspelled?), keeping old pin")

    out = ["# CPM Package Lock\n# Generated by lock-deps.py. Commit this file.\n\n"]
    for name, block in new.items():
        if a.cmd == "refresh" and (a.all or name in targets):
            block = pin(name, block)
        elif name in old:
            block = old[name]                 # pinned: untouched
        else:
            block = pin(name, block)          # new dependency
        out.append(f"# {name}\n{block}\n")

    if not a.prune:                           # e.g. packages under .developing: keep their pins
        for name, block in old.items():
            if name not in new:
                print(f"  {name}: not seen this configure, keeping old pin")
                out.append(f"# {name}\n{block}\n")

    tmp = a.lock + ".tmp"
    open(tmp, "w", encoding="utf-8").write("".join(out))
    os.replace(tmp, a.lock)
    print(f"wrote {a.lock}")


if __name__ == "__main__":
    main()
